insert into public.kb_recipes (id, method_id, submethod, name, author, source_id, evidence, role, dose_g, dose_max_g, brew_water_g, water_max_g, bypass_water_g, ice_g, beverage_out_g, temp_min_c, temp_max_c, grind, time_min_s, time_max_s, ratio_brew, ratio_espresso, roast, target_profile, gear, why, limits, url, verified_at, sort_order) values
  ('V60-001', 'V60', 'V60', 'Ultimate V60 30/500', 'James Hoffmann', 'S001', 'A', 'base', 30, null, 500, null, null, null, null, null, null, 'media-fina', 210, null, 16.67, null, 'claro/medio', 'balance / limpieza', 'V60, filtro, balanza, hervidor', 'Mojado completo, temperatura sostenida y cama relativamente uniforme favorecen extracción regular.', 'Temperatura sin cifra exacta: agua muy caliente, especialmente en tuestes claros. Tiempo depende de molino, papel y café.', 'https://www.hario-usa.com/blogs/recipes-and-more-from-friends/james-hoffmann-uitimate-v60-technique', '2026-11-10', 10),
  ('V60-002', 'V60', 'V60', 'Better 1 Cup V60', 'James Hoffmann', 'S002', 'A', 'base', 15, null, 250, null, null, null, null, null, null, 'media-fina', 180, null, 16.67, null, 'claro/medio', 'una taza, limpieza', 'V60, filtro de papel, hervidor', 'Con dosis pequeña, los vertidos espaciados mantienen suficiente interacción agua-café.', 'Secuencia basada en el video original; temperatura expresa agua recién hervida sin °C universal.', 'https://www.youtube.com/watch?v=1oB1oDrDkHM', '2026-11-10', 20),
  ('V60-003', 'V60', 'V60', '4:6 campeón Brewers Cup 2016', 'Tetsu Kasuya', 'S003', 'A', 'contextual', 20, null, 300, null, null, null, null, 92, null, 'gruesa', 210, null, 15, null, 'claro', 'dulzor y acidez expresiva', 'V60, agua 92°C', 'Diseño 4:6 divide agua inicial para balance y agua final para concentración percibida; mecanismo propuesto por Kasuya.', 'Nació como receta competitiva para Gesha natural; afirmaciones acidez/dulzor son hipótesis del autor.', 'https://kurasu.kyoto/blogs/kurasu-journal/2016-world-brewers-cup-champion-tetsu-kasuya', '2026-11-10', 30),
  ('V60-004', 'V60', 'V60', 'V60 Pete Licata', 'Pete Licata', 'S004', 'B', 'contextual', 18, null, 300, null, null, null, null, 94, null, 'media-fina', 150, null, 16.67, null, 'no especificado', 'aromático', 'V60', 'Intercala caudal y turbulencia para un objetivo de taza específico.', 'El fraccionamiento intermedio es operacionalmente reconstruido a partir de la guía; verificar al ejecutar.', 'https://www.hario-europe.com/blogs/hario-community/v60-ambassadors-pete-licata', '2026-11-10', 40),
  ('PO-001', 'Pour over genérico', 'Pour over genérico', 'Filtro Tim Wendelboe 65g/L', 'Tim Wendelboe', 'S005', 'A', 'base', 32.5, null, 500, null, null, null, null, null, null, 'filtro/media', 210, null, 15.38, null, 'no especificado', 'equilibrio', 'filtro compatible', '65g/L permite empezar con intensidad conocida y controlar molienda/flujo.', 'La fuente describe 65g/L; no publica temperatura única. En la fuente puede variar según cafetera.', 'https://timwendelboe.no/pages/how-to-brew-pourover-and-filter-coffee', '2026-11-10', 50),
  ('APR-001', 'April Brewer', 'April Brewer', 'Patrik Rolf 12/200', 'Patrik Rolf', 'S006', 'A', 'base', 12, null, 200, null, null, null, null, 92, null, 'media', 150, null, 16.67, null, 'no especificado', 'dulzor/claridad', 'April Brewer y papel April', 'Alterna vertidos circulares y centrales, controlando agitación y saturación.', 'Requiere dripper de April y su papel; transferirlo a V60 altera dinámica.', 'https://coffeewerkandpress.com/pages/brew-guide', '2026-11-10', 60),
  ('PO-002', 'Pour over genérico', 'Pour over genérico', 'Blue Bottle 20–27/350', 'Blue Bottle Coffee', 'S007', 'A', 'base', 20, 27, 350, null, null, null, null, 91, 96, 'media', 150, 210, 17.5, null, 'no especificado', 'filtro de cafetería', 'dripper de papel', 'Pulsos facilitan observar y mantener saturación uniforme.', 'Dosis y temperatura son rangos originales: 20–27g y 195–205°F (91–96°C). No suponer un único ratio.', 'https://bluebottlecoffee.com/us/eng/brew-guides/pour-over', '2026-11-10', 70),
