  ('PHIN-001', 'Phin vietnamita', 'Phin vietnamita', 'Nguyen tradicional 14g/4oz', 'Nguyen Coffee Supply', 'S034', 'B', 'base', 14, null, 118, null, null, null, null, 91, null, 'media-fina (phin)', 300, null, 8.43, null, 'medio/oscuro/robusta opcional', 'intenso', 'filtro phin vietnamita', 'Placa perforada ofrece goteo lento y alta intensidad; puede mezclarse con leche condensada.', 'Equivalencia oz->g aproximada; la página contiene un ratio escrito incompatible con 14g y 4oz: se prioriza dosificación explícita.', 'https://nguyencoffeesupply.com/blogs/vietnamese-coffee-brew-guide/traditional-vietnamese-drip-phin', '2026-11-10', 510),
  ('SYP-001', 'Sifón', 'Sifón', 'Morgan Eckroth Hario Syphon', 'Morgan Eckroth', 'S035', 'B', 'contextual', 36, null, 560, null, null, null, null, null, null, null, 150, null, 15.56, null, 'no especificado', 'aromático / limpio', 'sifón Hario + quemador', 'El cambio presión/vacío y el filtrado separan café de infusión.', 'Fuente no cuantifica temperatura y etapas con suficiente detalle; pasos resumidos son una descripción operativa, no minutado exacto.', 'https://www.hario-usa.com/blogs/syphon-recipes-and-guides/morgan-eckroth-syphon-brewing', '2026-11-10', 520),
  ('NEL-001', 'Nel drip', 'Nel drip', 'Blue Bottle Nel Drip inconsistencia', 'Blue Bottle Coffee', 'S036', 'B', 'revisar', 25, null, 185, null, null, null, null, 79, null, 'muy gruesa', 200, null, 7.4, null, 'oscuro (ejemplo Tokyo Kissa)', 'textura', 'nel filter textil', 'Filtro textil y caudal lento generan cuerpo diferente al papel.', 'CRÍTICO: encabezado dice 250g pero 45+80+60=185g; excluir del motor hasta auditoría. Temperatura aprox 175–180°F.', 'https://bluebottlecoffee.com/us/eng/brew-guides/nel-drip', '2026-11-10', 530),
  ('CB-001', 'Cold brew', 'Cold brew', 'Counter Culture preinfusión tibia 200/1600', 'Counter Culture Coffee', 'S037', 'A', 'base', 200, null, 1600, null, null, null, null, null, null, 'gruesa', 21600, null, 8, null, 'cualquiera', 'concentrado/frío', 'recipiente y filtro, refrigerador', 'Infusión a menor temperatura durante horas aporta perfil distinto; prehumectación mejora mojado.', 'No registrar 77°C como temperatura de TODA agua; mezcla 300g caliente +1300g ambiente. 6h mínimo.', 'https://counterculturecoffee.com/pages/cold-brew', '2026-11-10', 540),
  ('CB-002', 'Cold brew', 'Cold brew', 'Stumptown Filtron 12oz / 56 fl oz', 'Stumptown Coffee', 'S038', 'B', 'contextual', 340, null, 1656, null, null, null, null, null, null, 'gruesa', 43200, 86400, 4.87, null, 'no especificado', 'concentrado', 'Filtron', 'Filtración separada tras inmersión larga produce concentrado utilizable en varias bebidas.', '12oz son ~340g café por peso; 56 US fl oz son ~1656mL de agua, conversiones editoriales aproximadas.', 'https://www.stumptowncoffee.com/pages/brew-guide-filtron', '2026-11-10', 550),
  ('CB-003', 'Cold brew', 'Cold brew', 'Blue Bottle Hario Bottle 55/700', 'Blue Bottle Coffee', 'S039', 'A', 'base', 55, null, 700, null, null, null, null, null, null, 'media-gruesa', 28800, null, 12.73, null, 'no especificado', 'cold brew listo', 'Hario cold brew bottle 700ml', 'Sistema cerrado con filtro facilita replicabilidad doméstica.', 'No confundir con cold brew concentrado: dosificación de bebida lista para servir.', 'https://bluebottlecoffee.com/us/eng/brew-guides/cold-brew-bottle', '2026-11-10', 560),
  ('ICE-001', 'Flash brew', 'Flash brew', 'Blue Bottle Hot Over Ice', 'Blue Bottle Coffee', 'S040', 'A', 'base', 20, 27, 200, null, null, 75, null, 93.3, null, 'media', 105, 135, 10, null, 'no especificado', 'frutal frío', 'dripper, jarra y hielo', 'Menor agua caliente compensa el hielo que se derrite y enfría sin larga oxidación.', 'La dosis original admite 20–27g, usar 20g como extremo publicado; hielo 75g separado.', 'https://bluebottlecoffee.com/us/eng/brew-guides/hot-over-ice', '2026-11-10', 570),
  ('ICE-002', 'Iced coffee refrigerado', 'Iced coffee refrigerado', 'Tim Wendelboe iced filter', 'Tim Wendelboe', 'S041', 'A', 'base', 30, null, 500, null, null, null, null, null, null, 'filtro', 180, null, 16.67, null, 'no especificado', 'frío ligero', 'dripper y refrigerador', 'Mantiene receta filtrada caliente y posteriormente reduce temperatura.', 'No confundir con método flash brew, donde hielo va en jarra desde el comienzo.', 'https://timwendelboe.no/pages/how-to-make-iced-coffee', '2026-11-10', 580),
  ('KAL-003', 'Kalita Wave', 'Kalita Wave', 'Onyx Power Nap 25/400', 'Onyx Coffee Lab', 'S012', 'A', 'contextual', 25, null, 400, null, null, null, null, 96.1, null, 'media-gruesa (750µm)', 270, null, 16, null, 'blend Power Nap', 'dulzor', 'Kalita Wave', 'Tostador optimizó distribución de pulsos para mezcla Power Nap.', 'Largo drenaje diseñado para café particular; no fijar 4:30 como objetivo universal de Kalita.', 'https://onyxcoffeelab.com/pages/brew-guides', '2026-11-10', 590),
  ('KAL-004', 'Kalita Wave', 'Kalita Wave', 'Onyx Southern Weather 25/300', 'Onyx Coffee Lab', 'S012', 'A', 'contextual', 25, null, 300, null, null, null, null, 93.3, null, 'media', 150, null, 12, null, 'blend Southern Weather', 'intenso', 'Kalita Wave', 'Ratio concentrado adaptado a esa mezcla; posibilita mayor intensidad sensorial.', 'Solo ejemplo para blend Southern Weather, no base 1:12 en café claro universal.', 'https://onyxcoffeelab.com/pages/brew-guides', '2026-11-10', 600),
  ('ESP-006', 'Espresso', 'Espresso', 'Onyx Seasonal East Africa 19/40', 'Onyx Coffee Lab', 'S012', 'A', 'contextual', 19, null, null, null, null, null, 40, null, null, 'espresso específica', 27, null, null, 2.11, 'Seasonal East Africa', 'frutal', 'máquina espresso con control de presión', 'Dial-in empírico publicado por tostador para lote determinado.', 'Onyx usa perfiles de presión 0–3.5bar y 9bar; no transferir sin máquina compatible.', 'https://onyxcoffeelab.com/pages/brew-guides', '2026-11-10', 610)
