  ('SWT-001-03', 'SWT-001', 3, 90, 'switch cerrado', 90, 240, null, 'Cerrar a 1:30 y agregar 90g.', 'Segunda inmersión.', 'S021', 'https://www.hario-europe.com/blogs/hario-community/ole-kristian-boens-switch-recipe'),
  ('SWT-001-04', 'SWT-001', 4, 130, 'switch abierto', null, 240, null, 'Abrir a 2:10.', 'Completar drenaje.', 'S021', 'https://www.hario-europe.com/blogs/hario-community/ole-kristian-boens-switch-recipe'),
  ('SWT-001-05', 'SWT-001', 5, 195, 'fin', null, 240, null, 'Taza a 3:00–3:15.', 'Tiempo referencia.', 'S021', 'https://www.hario-europe.com/blogs/hario-community/ole-kristian-boens-switch-recipe'),
  ('SWT-002-01', 'SWT-002', 1, 0, 'válvula cerrada', 100, 100, 86, 'Añadir 100g a 86°C, mantener 40s.', 'Primera fase más fría.', 'S022', 'https://www.hario-europe.com/blogs/hario-community/interview-with-ryan-wibawa-switch-recipe'),
  ('SWT-002-02', 'SWT-002', 2, 40, 'válvula abierta', null, 100, null, 'Abrir válvula y dejar filtrar.', 'Separar fases.', 'S022', 'https://www.hario-europe.com/blogs/hario-community/interview-with-ryan-wibawa-switch-recipe'),
  ('SWT-002-03', 'SWT-002', 3, 50, 'válvula cerrada', 120, 220, 92, 'Volver a cerrar y añadir 120g a 92°C.', 'Segunda infusión más caliente.', 'S022', 'https://www.hario-europe.com/blogs/hario-community/interview-with-ryan-wibawa-switch-recipe'),
  ('SWT-002-04', 'SWT-002', 4, 115, 'válvula abierta', null, 220, null, 'Abrir tras 1:05 de segunda fase.', 'Drenar.', 'S022', 'https://www.hario-europe.com/blogs/hario-community/interview-with-ryan-wibawa-switch-recipe'),
  ('SWT-003-01', 'SWT-003', 1, 0, 'válvula abierta', 30, 30, null, 'Agregar 30g con válvula abierta.', 'Bloom con percolación.', 'S023', 'https://www.hario-usa.com/blogs/recipes-and-more-from-friends/v60-switch-recipe-with-partners-coffee'),
  ('SWT-003-02', 'SWT-003', 2, 55, 'vertido abierto', 110, 140, null, 'Llegar a 140g a 0:55.', 'Filtrar primera fracción.', 'S023', 'https://www.hario-usa.com/blogs/recipes-and-more-from-friends/v60-switch-recipe-with-partners-coffee'),
  ('SWT-003-03', 'SWT-003', 3, 75, 'válvula cerrada', 100, 240, null, 'Cerrar a 1:15 y añadir 100g.', 'Fase inmersión.', 'S023', 'https://www.hario-usa.com/blogs/recipes-and-more-from-friends/v60-switch-recipe-with-partners-coffee'),
  ('SWT-003-04', 'SWT-003', 4, 150, 'válvula abierta', null, 240, null, 'Abrir a 2:30.', 'Separar café.', 'S023', 'https://www.hario-usa.com/blogs/recipes-and-more-from-friends/v60-switch-recipe-with-partners-coffee'),
  ('SWT-003-05', 'SWT-003', 5, 240, 'fin', null, 240, null, 'Retirar a 4:00.', 'Protocolo fuente.', 'S023', 'https://www.hario-usa.com/blogs/recipes-and-more-from-friends/v60-switch-recipe-with-partners-coffee'),
  ('ESP-001-01', 'ESP-001', 1, 0, 'preparar', null, null, null, 'Distribuir y prensar 20g en canasto VST 20g.', 'Evitar canalización.', 'S027', 'https://timwendelboe.no/pages/how-we-make-espresso-espresso-tips'),
  ('ESP-001-02', 'ESP-001', 2, 0, 'extraer', null, null, null, 'Obtener ~45g de bebida en 25–35s a 93–94°C.', 'Relación bebida/dosis ~2.25.', 'S027', 'https://timwendelboe.no/pages/how-we-make-espresso-espresso-tips'),
  ('ESP-001-03', 'ESP-001', 3, 30, 'evaluar', null, null, null, 'Ajustar molienda por peso final y sabor.', 'Diagnóstico iterativo.', 'S027', 'https://timwendelboe.no/pages/how-we-make-espresso-espresso-tips'),
  ('ESP-002-01', 'ESP-002', 1, 0, 'preparar', null, null, null, 'Dosificar 19.5g, distribuir y prensar.', 'Uniformidad de flujo.', 'S028', 'https://www.stumptowncoffee.com/pages/brew-guide-espresso'),
  ('ESP-002-02', 'ESP-002', 2, 0, 'extraer', null, null, null, 'Obtener 24–28g en 23–28s.', 'Espresso corto propio del blend.', 'S028', 'https://www.stumptowncoffee.com/pages/brew-guide-espresso'),
  ('ESP-003-01', 'ESP-003', 1, 0, 'preparar', null, null, null, 'Dosificar 20g y distribuir muy uniformemente.', 'Evita canales.', 'S029', 'https://bluebottlecoffee.com/us/eng/brew-guides/espresso'),
  ('ESP-003-02', 'ESP-003', 2, 0, 'extraer', null, null, null, 'Extraer hasta 22g en 28–38s.', 'Ristretto de relación corta.', 'S029', 'https://bluebottlecoffee.com/us/eng/brew-guides/espresso'),
  ('ESP-004-01', 'ESP-004', 1, 0, 'preparar', null, null, null, 'Pesar 20g en canasto.', 'Control de dosis.', 'S030', 'https://bluebottlecoffee.com/us/eng/brew-guides/single-origin-espresso'),
  ('ESP-004-02', 'ESP-004', 2, 0, 'extraer', null, null, null, 'Obtener 40g de espresso en 28–32s.', 'Taza 1:2 por masa.', 'S030', 'https://bluebottlecoffee.com/us/eng/brew-guides/single-origin-espresso'),
  ('ESP-005-01', 'ESP-005', 1, 0, 'preparación', null, null, null, 'Escoger dosis según canasto y café, habitualmente 18–20g en la encuesta.', 'Referencia descriptiva, no prescriptiva.', 'S031', 'https://sca.coffee/sca-news/25-magazine/issue-3/defining-ever-changing-espresso-25-magazine-issue-3-zyx36'),
  ('ESP-005-02', 'ESP-005', 2, 0, 'extracción', null, null, null, 'Referencia aprox. 36.5g de bebida, 25–30s y 9 bar.', 'Uso como punto de comparación.', 'S031', 'https://sca.coffee/sca-news/25-magazine/issue-3/defining-ever-changing-espresso-25-magazine-issue-3-zyx36'),
  ('MOK-001-01', 'MOK-001', 1, 0, 'llenado', null, null, null, 'Llenar canasta hasta borde sin prensar; agua previamente caliente por debajo de válvula.', 'Respeta geometría y seguridad de moka.', 'S032', 'https://www.youtube.com/watch?v=BfDLoIvb0w4'),
  ('MOK-001-02', 'MOK-001', 2, 0, 'calor', null, null, null, 'Fuego medio-bajo; controlar caudal.', 'Evitar ebullición agresiva.', 'S032', 'https://www.youtube.com/watch?v=BfDLoIvb0w4'),
  ('MOK-001-03', 'MOK-001', 3, 0, 'retirar', null, null, null, 'Cuando comience a borbotear, retirar y enfriar base; servir.', 'Evitar sobrecalentar al final.', 'S032', 'https://www.youtube.com/watch?v=BfDLoIvb0w4'),
  ('CEZ-001-01', 'CEZ-001', 1, 0, 'mezclar', null, null, null, 'Poner porción 6g por taza pequeña, agregar una taza de agua fría y azúcar opcional.', 'Dispersión antes del calor.', 'S033', 'https://www.mehmetefendi.com/eng/brew-guide/turkish-coffee/with-cezve'),
  ('CEZ-001-02', 'CEZ-001', 2, 0, 'calentar', null, null, null, 'Calentar lentamente evitando hervir de forma violenta.', 'Formación de espuma y textura.', 'S033', 'https://www.mehmetefendi.com/eng/brew-guide/turkish-coffee/with-cezve'),
  ('CEZ-001-03', 'CEZ-001', 3, 120, 'servir', null, null, null, 'Retirar con espuma y servir sin filtrar.', 'Método de suspensión.', 'S033', 'https://www.mehmetefendi.com/eng/brew-guide/turkish-coffee/with-cezve'),
  ('PHIN-001-01', 'PHIN-001', 1, 0, 'bloom', 30, 30, null, 'Agregar 1oz (~30mL) de agua por 45s.', 'Humedecer café.', 'S034', 'https://nguyencoffeesupply.com/blogs/vietnamese-coffee-brew-guide/traditional-vietnamese-drip-phin'),
  ('PHIN-001-02', 'PHIN-001', 2, 45, 'vertido', 88, 118, null, 'Completar el agua hasta 4oz (~118mL).', 'Goteo por gravedad.', 'S034', 'https://nguyencoffeesupply.com/blogs/vietnamese-coffee-brew-guide/traditional-vietnamese-drip-phin'),
  ('PHIN-001-03', 'PHIN-001', 3, 300, 'fin', null, 118, null, 'Goteo debería acabar alrededor de 5min.', 'Verificar compactación y molienda.', 'S034', 'https://nguyencoffeesupply.com/blogs/vietnamese-coffee-brew-guide/traditional-vietnamese-drip-phin'),
  ('SYP-001-01', 'SYP-001', 1, 0, 'montaje', null, null, null, 'Instalar filtro, calentar 560g de agua hasta subir a cámara superior.', 'Sifón por presión de vapor.', 'S035', 'https://www.hario-usa.com/blogs/syphon-recipes-and-guides/morgan-eckroth-syphon-brewing'),
  ('SYP-001-02', 'SYP-001', 2, 0, 'infusión', null, 560, null, 'Incorporar 36g café y seguir secuencia original.', 'Contacto con agua caliente.', 'S035', 'https://www.hario-usa.com/blogs/syphon-recipes-and-guides/morgan-eckroth-syphon-brewing'),
  ('SYP-001-03', 'SYP-001', 3, 150, 'retirar calor', null, 560, null, 'Retirar calor para permitir descenso por vacío.', 'Filtrado por gradiente presión.', 'S035', 'https://www.hario-usa.com/blogs/syphon-recipes-and-guides/morgan-eckroth-syphon-brewing'),
  ('NEL-001-01', 'NEL-001', 1, 0, 'bloom', 45, 45, null, 'Añadir ~45g durante 45s.', 'Preinfusión lenta.', 'S036', 'https://bluebottlecoffee.com/us/eng/brew-guides/nel-drip'),
  ('NEL-001-02', 'NEL-001', 2, 90, 'vertido', 80, 125, null, 'Añadir 80g durante 60s.', 'Flujo lento.', 'S036', 'https://bluebottlecoffee.com/us/eng/brew-guides/nel-drip'),
  ('NEL-001-03', 'NEL-001', 3, 170, 'vertido', 60, 185, null, 'Añadir 60g durante 30s.', 'Completar pasos publicados.', 'S036', 'https://bluebottlecoffee.com/us/eng/brew-guides/nel-drip'),
  ('NEL-001-04', 'NEL-001', 4, 200, 'fin', null, 185, null, 'Fin ~3:20.', 'Confirmar antes de automatizar.', 'S036', 'https://bluebottlecoffee.com/us/eng/brew-guides/nel-drip'),
  ('CB-001-01', 'CB-001', 1, 0, 'preinfusión tibia', 300, 300, null, 'Agregar 300g agua ~77°C por 3min.', 'Primera humectación.', 'S037', 'https://counterculturecoffee.com/pages/cold-brew'),
  ('CB-001-02', 'CB-001', 2, 180, 'agua fría', 1300, 1600, null, 'Agregar 1300g agua a temperatura ambiente, refrigerar mínimo 6h.', 'Extracción prolongada a baja temperatura.', 'S037', 'https://counterculturecoffee.com/pages/cold-brew'),
  ('CB-001-03', 'CB-001', 3, 21600, 'filtrar', null, 1600, null, 'Filtrar concentrado; diluir 1:1 al servir.', 'Concentración final.', 'S037', 'https://counterculturecoffee.com/pages/cold-brew'),
  ('CB-002-01', 'CB-002', 1, 0, 'mojar', 1656, 1656, null, 'Incorporar aprox. 56 fl oz de agua fría al sistema Filtron.', 'Inicio extracción.', 'S038', 'https://www.stumptowncoffee.com/pages/brew-guide-filtron'),
  ('CB-002-02', 'CB-002', 2, 57600, 'filtrar', null, 1656, null, 'Reposar 12–24h, preferencia del autor 16h, luego filtrar.', 'Concentrado.', 'S038', 'https://www.stumptowncoffee.com/pages/brew-guide-filtron'),
  ('CB-002-03', 'CB-002', 3, 57600, 'diluir', null, 1656, null, 'Al servir, diluir 1 parte concentrado por 2 partes agua.', 'Fuerza final.', 'S038', 'https://www.stumptowncoffee.com/pages/brew-guide-filtron'),
  ('CB-003-01', 'CB-003', 1, 0, 'inmersión', 700, 700, null, 'Introducir 55g café al filtro y 700mL agua fría.', 'Contacto completo.', 'S039', 'https://bluebottlecoffee.com/us/eng/brew-guides/cold-brew-bottle'),
  ('CB-003-02', 'CB-003', 2, 0, 'mezclar', null, 700, null, 'Mover la botella suavemente de lado a lado, sin invertir.', 'Mojado uniforme.', 'S039', 'https://bluebottlecoffee.com/us/eng/brew-guides/cold-brew-bottle'),
  ('CB-003-03', 'CB-003', 3, 28800, 'retirar', null, 700, null, 'Retirar filtro tras 8h, servir frío.', 'Corta el contacto.', 'S039', 'https://bluebottlecoffee.com/us/eng/brew-guides/cold-brew-bottle'),
  ('ICE-001-01', 'ICE-001', 1, 0, 'hielo', null, null, null, 'Poner 75g hielo en servidor.', 'Enfriar al recibir café.', 'S040', 'https://bluebottlecoffee.com/us/eng/brew-guides/hot-over-ice'),
  ('ICE-001-02', 'ICE-001', 2, 0, 'bloom', 50, 50, null, 'Agregar 50g de agua caliente.', 'Mojar café.', 'S040', 'https://bluebottlecoffee.com/us/eng/brew-guides/hot-over-ice'),
  ('ICE-001-03', 'ICE-001', 3, 40, 'vertido', 70, 120, null, 'Llegar a 120g.', 'Extracción.', 'S040', 'https://bluebottlecoffee.com/us/eng/brew-guides/hot-over-ice'),
  ('ICE-001-04', 'ICE-001', 4, 70, 'vertido', 80, 200, null, 'Llegar a 200g.', 'Completar.', 'S040', 'https://bluebottlecoffee.com/us/eng/brew-guides/hot-over-ice'),
  ('ICE-001-05', 'ICE-001', 5, 135, 'fin', null, 200, null, 'Tiempo 1:45–2:15; agitar bebida e hielo.', 'Enfriamiento inmediato.', 'S040', 'https://bluebottlecoffee.com/us/eng/brew-guides/hot-over-ice'),
  ('ICE-002-01', 'ICE-002', 1, 0, 'bloom', 60, 60, null, 'Bloom 60g de agua caliente.', 'Humedecer.', 'S041', 'https://timwendelboe.no/pages/how-to-make-iced-coffee'),
  ('ICE-002-02', 'ICE-002', 2, 30, 'vertido', 140, 200, null, 'Llegar a 200g.', 'Inicio.', 'S041', 'https://timwendelboe.no/pages/how-to-make-iced-coffee'),
  ('ICE-002-03', 'ICE-002', 3, 100, 'vertido', 300, 500, null, 'Completar 500g, terminar ~3min.', 'Extracción regular.', 'S041', 'https://timwendelboe.no/pages/how-to-make-iced-coffee'),
  ('ICE-002-04', 'ICE-002', 4, 180, 'refrigerar', null, 500, null, 'Enfriar en refrigerador y servir sobre hielo.', 'Disminuir temperatura después de extracción.', 'S041', 'https://timwendelboe.no/pages/how-to-make-iced-coffee'),
  ('KAL-003-01', 'KAL-003', 1, 0, 'bloom', 50, 50, null, 'Agregar 50g.', 'Bloom.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides'),
  ('KAL-003-02', 'KAL-003', 2, 30, 'vertido', 110, 160, null, 'Hasta 160g.', 'Pulso.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides'),
  ('KAL-003-03', 'KAL-003', 3, 45, 'vertido', 60, 220, null, 'Hasta 220g.', 'Pulso.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides'),
