  ('KAL-004-01', 'KAL-004', 1, 0, 'bloom', 40, 40, null, 'Bloom 40g.', 'Mojar.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides'),
  ('KAL-004-02', 'KAL-004', 2, 30, 'vertido', 80, 120, null, 'Hasta 120g.', 'Pulso.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides'),
