  ('ESP-006-01', 'ESP-006', 1, 0, 'preparar', null, null, null, 'Dosificar 19g y distribuir sin canalización.', 'Uniformidad.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides'),
  ('ESP-006-02', 'ESP-006', 2, 0, 'extraer', null, null, null, 'Objetivo 40g de bebida en 27s según lote.', 'Balance para ese café.', 'S012', 'https://onyxcoffeelab.com/pages/brew-guides')
insert into public.kb_rules (id, kind, title, rule, category, signal, method, hypothesis, action, variable, magnitude, outcome, caveat, source_id, confidence) values
  ('P01', 'principle', 'Ratio no es extracción', 'Razón agua de infusión / café describe receta; espresso usa masa bebida / dosis. No mezclarlas.', 'medición', null, null, null, null, null, null, null, 'No usar g agua para inferir rendimiento espresso.', 'S046', 'alta'),
  ('P02', 'principle', 'Cambiar una variable', 'Para interpretar resultados mantener constantes dosis, agua, método, filtro y cambiar una variable a la vez.', 'experimentación', null, null, null, null, null, null, null, 'No garantiza causalidad si cambia temperatura ambiente, agua u operador.', 'S047', 'editorial'),
  ('P03', 'principle', 'Pesar dosis y bebida', 'Medir gramos es más reproducible que cucharadas/volumen. En espresso registrar masa bebida.', 'medición', null, null, null, null, null, null, null, 'El agua inicial del filtro NO equivale a bebida final.', 'S027', 'alta'),
  ('P04', 'principle', 'Mojado de bloom', 'Preinfusión humedece cama y permite expulsión parcial de CO2; duración y volumen varían.', 'extracción', null, null, null, null, null, null, null, 'No exigir 30s ni bloom idéntico en inmersión.', 'S001', 'media'),
  ('P05', 'principle', 'Molienda y superficie', 'Más fina aumenta superficie disponible y resistencia de flujo en percolación.', 'extracción', null, null, null, null, null, null, null, 'Finura extrema puede generar bypass/canalización/obstrucción.', 'S010', 'alta'),
  ('P06', 'principle', 'Agua más caliente', 'Puede favorecer extracción de compuestos y compensar tueste claro; temperatura óptima depende de tueste.', 'temperatura', null, null, null, null, null, null, null, 'No recomendar hervir en recetas explícitas a baja temperatura.', 'S015', 'media'),
  ('P07', 'principle', 'Calidad del agua', 'Alcalinidad/mineralización modifica percepción y extracción; medir composición si es posible.', 'agua', null, null, null, null, null, null, null, 'No prescribir agua pura desmineralizada como universal.', 'S046', 'alta'),
  ('P08', 'principle', 'Cama uniforme', 'Nivelar y mojar la cama reduce riesgo de zonas secas, pero sobreagitación puede movilizar finos.', 'técnica', null, null, null, null, null, null, null, 'En algunos métodos (AeroPress campeón) se agita mucho por diseño.', 'S001', 'media'),
  ('P09', 'principle', 'Tiempo no es calidad', 'Tiempo funciona como señal junto con molienda/flujo/sabor, no única meta.', 'diagnóstico', null, null, null, null, null, null, null, 'No ajustar molienda solo por alcanzar un tiempo exacto.', 'S010', 'alta'),
  ('P10', 'principle', 'Papel cambia cuerpo', 'Chemex y otros filtros gruesos alteran retención de aceites/fino y caudal.', 'filtro', null, null, null, null, null, null, null, 'No atribuir todas las diferencias únicamente al papel.', 'S015', 'alta'),
  ('P11', 'principle', 'Inmersión vs percolación', 'Inmersión equilibra interacción en volumen; percolación aporta agua nueva y depende del flujo.', 'método', null, null, null, null, null, null, null, 'No copiar calendario de V60 a French Press.', 'S020', 'alta'),
  ('P12', 'principle', 'Clever water-first', 'Llenar con agua antes que café reduce sellado inicial de finos en receta oficial Clever.', 'técnica', null, null, null, null, null, null, null, 'No extrapolar a V60 abierto.', 'S020', 'media'),
  ('P13', 'principle', 'Bypass separado', 'El agua añadida después de extraer cambia concentración, no extracción primaria.', 'medición', null, null, null, null, null, null, null, 'Reportar agua infusión vs bypass por separado.', 'S026', 'alta'),
  ('P14', 'principle', 'Hielo separado', 'Flash brew sustituye parte del agua por hielo de recepción; distingue hielo del agua caliente.', 'medición', null, null, null, null, null, null, null, 'Registrar si el hielo realmente se derritió.', 'S040', 'alta'),
  ('P15', 'principle', 'Temperaturas múltiples', 'En recetas con agua a varias temperaturas no promediar sin fundamento.', 'medición', null, null, null, null, null, null, null, 'Registrar temp de cada paso.', 'S026', 'alta'),
  ('P16', 'principle', 'No todos los tiempos comparables', 'Tiempo total vs duración de infusión vs tiempo de presión son magnitudes diferentes.', 'medición', null, null, null, null, null, null, null, 'Tomar t0 al primer contacto según protocolo específico.', 'S018', 'alta'),
  ('P17', 'principle', 'Tueste y solubilidad', 'Tuestes oscuros suelen aceptar temperaturas inferiores según receta de tostadores; validar con cata.', 'temperatura', null, null, null, null, null, null, null, 'No tratar origen como variable que determina temperatura por sí sola.', 'S007', 'media'),
  ('P18', 'principle', 'Extraer no es gustar', 'Un TDS/EY objetivo no garantiza preferencia; separar medición técnica de agrado subjetivo.', 'sensorial', null, null, null, null, null, null, null, 'Gold Cup del programa de máquinas no es ley para espresso o AeroPress.', 'S045', 'alta'),
  ('P19', 'principle', 'Gold Cup contextual', 'En certificación máquinas domésticas se ensaya TDS 1.15–1.45% y EY 18–22%, inicio 55g/L.', 'estándar', null, null, null, null, null, null, null, 'Solo protocolo de certificado doméstico; no universalizar.', 'S045', 'alta'),
  ('P20', 'principle', 'Agua no evaporada', 'El rendimiento en taza es menor a agua vertida por retención de café/filtro, especialmente filtro.', 'medición', null, null, null, null, null, null, null, 'No calcular bebida final = agua añadida.', 'S008', 'alta'),
  ('P21', 'principle', 'Recetas son anclas', 'Una receta oficial es punto de partida, no validación independiente universal ni prueba causal.', 'metodología', null, null, null, null, null, null, null, 'Registrar fuente, equipo y café original.', 'S003', 'alta'),
  ('P22', 'principle', 'Competición contextual', 'Premios de AeroPress pueden exigir tamiz, bypass, agua especial o ratio de concentrado poco cotidiano.', 'calidad', null, null, null, null, null, null, null, 'En búsqueda inicial mostrar base antes de competición.', 'S026', 'alta'),
  ('P23', 'principle', 'Descripción sensorial vs gusto', 'Separar notas descriptivas (ácido, floral, amargo) y juicio hedónico (me gusta 1-5).', 'evaluación', null, null, null, null, null, null, null, 'El usuario puede gustar de alta acidez.', 'S047', 'alta'),
  ('P24', 'principle', 'Seguridad moka e invertida', 'No llenar encima de válvula moka; evitar vuelcos de AeroPress invertida con agua caliente.', 'seguridad', null, null, null, null, null, null, null, 'Seguir manual del fabricante, siempre.', 'S032', 'alta'),
  ('P25', 'principle', 'Tratamiento de conflictos', 'Si encabezado y pasos de fuente se contradicen, excluir y elevar incidencia.', 'ingesta', null, null, null, null, null, null, null, 'No rellenar diferencias automáticamente.', 'S036', 'alta'),
