-- Seed de la base de conocimiento de recetas. Generado por scripts/kb_seed.py desde docs/kb/*. No editar a mano.
-- 48 fuentes, 21 métodos, 61 recetas, 236 pasos, 71 reglas.
begin;
on conflict (id) do update set editor = excluded.editor, author = excluded.author, title = excluded.title, kind = excluded.kind, year = excluded.year, url = excluded.url, warning = excluded.warning, consulted_at = excluded.consulted_at;

on conflict (id) do update set physics = excluded.physics, geometry = excluded.geometry, filter = excluded.filter, difficulty = excluded.difficulty, ratio_type = excluded.ratio_type, ratio_note = excluded.ratio_note, distinctive = excluded.distinctive, source_id = excluded.source_id, url = excluded.url, sort_order = excluded.sort_order;

on conflict (id) do update set method_id = excluded.method_id, submethod = excluded.submethod, name = excluded.name, author = excluded.author, source_id = excluded.source_id, evidence = excluded.evidence, role = excluded.role, dose_g = excluded.dose_g, dose_max_g = excluded.dose_max_g, brew_water_g = excluded.brew_water_g, water_max_g = excluded.water_max_g, bypass_water_g = excluded.bypass_water_g, ice_g = excluded.ice_g, beverage_out_g = excluded.beverage_out_g, temp_min_c = excluded.temp_min_c, temp_max_c = excluded.temp_max_c, grind = excluded.grind, time_min_s = excluded.time_min_s, time_max_s = excluded.time_max_s, ratio_brew = excluded.ratio_brew, ratio_espresso = excluded.ratio_espresso, roast = excluded.roast, target_profile = excluded.target_profile, gear = excluded.gear, why = excluded.why, limits = excluded.limits, url = excluded.url, verified_at = excluded.verified_at, sort_order = excluded.sort_order;

on conflict (id) do update set recipe_id = excluded.recipe_id, step_order = excluded.step_order, t_from_start_s = excluded.t_from_start_s, phase = excluded.phase, add_water_g = excluded.add_water_g, cumulative_water_g = excluded.cumulative_water_g, temp_c = excluded.temp_c, instruction = excluded.instruction, why = excluded.why, source_id = excluded.source_id, url = excluded.url;

on conflict (id) do update set kind = excluded.kind, title = excluded.title, rule = excluded.rule, category = excluded.category, signal = excluded.signal, method = excluded.method, hypothesis = excluded.hypothesis, action = excluded.action, variable = excluded.variable, magnitude = excluded.magnitude, outcome = excluded.outcome, caveat = excluded.caveat, source_id = excluded.source_id, confidence = excluded.confidence;

commit;